import{z as A,x as d,o as E,c as B,q as o,j as s,D as t,d as r,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"多空股票","description":"","frontmatter":{"title":"多空股票","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/long-short-equity.md","filePath":"quant/long-short-equity.md","lastUpdated":1791063341000}'),p={name:"quant/long-short-equity.md"};function h(u,a,m,c,f,q){const n=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="多空股票" tabindex="-1">多空股票 <a class="header-anchor" href="#多空股票" aria-label="Permalink to &quot;多空股票&quot;">​</a></h1><div class="epigraph"><p>多空不是两个多头相减那么简单；短腿有借券、召回与不对称的挤仓，多腿有资金与指数期货对冲的基差。</p><footer>—— 对照 Jacobs and Levy 对多空与 130/30 的讨论；因子多空见 Fama–French 排序</footer></div><p><a href="/quant/rebalancing-premium">上一课</a>收口多期配置。策略地图从多空股票起：主干 <a href="/quant/long-short-sort">单因子排序与多空</a> 已写截面构造。缺口是<strong>作为基金策略的实施</strong>：总暴露、净暴露、借券、对冲工具，以及它和 130/30 的差别。后课 130/30 是多头加有限短。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场中性多空目标净暴露近 0、总暴露 \\(2\\times\\)（或多空各 1）。因子溢价课里的 HML 是学术组合，不计借券稀缺与召回。实盘短腿成本随名字变化，拥挤时 <a href="/quant/cn-short-constraint">短约束</a> 与一般 <a href="/quant/securities-lending">证券借贷</a> 会把理论空头变成不可执行。问题是把策略定义成：可借券宇宙上的优化，而不是「把学术空头原样下单」。</p><p>净暴露若用股指期货对冲，留下基差与成分错配，中性变成「对指数中性」而非对全部风险因子中性，见 <a href="/quant/fundamental-risk-model">基本面风险模型</a>。</p><p><span class="marginnote">净暴露与总暴露翻译成大白话：净暴露是多腿减空腿后剩下的方向性仓位（还押不押大盘）；总暴露是多腿加空腿之和（用多少本钱同时持有两边）。「净 0、总 2×」就是一手多一手空各一倍本金——方向对冲掉了，但两头都要付交易与借券成本。</span></p><h3 id="总暴露才是风险预算的单位" tabindex="-1">总暴露才是风险预算的单位 <a class="header-anchor" href="#总暴露才是风险预算的单位" aria-label="Permalink to &quot;总暴露才是风险预算的单位&quot;">​</a></h3><p>报「我们市场中性」却 300% 总暴露，主动风险可以很大。限额应同时管净、总、因子、行业。多空的 IR 若用净资产当分母，会与用总暴露当分母的学术夏普不可比。</p><p><span class="marginnote">多空不是方向性择时。净暴露若随观点大幅摆动，应归入后课全球宏观或 130/30，不要留在中性桶里自我陈述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宇宙：可借、流动性、公司行动。优化：多空约束、因子中性、换手，见 <a href="/quant/long-short-constraints">多空约束</a>。执行：短腿优先确认可借再卖。对冲残差用期货时单独报基差。容量：短腿往往先满，见 <a href="/quant/strategy-capacity">策略容量</a>。</p>',12)),(E(),s(i,null,{default:t(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Univ%5B%22%E5%AE%87%E5%AE%99%3A%20%E5%8F%AF%E5%80%9F%20%2B%20%E6%B5%81%E5%8A%A8%E6%80%A7%20%2B%20%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%22%5D%20--%3E%20Opt%5B%22%E4%BC%98%E5%8C%96%3A%20%E7%BA%A6%E6%9D%9F%20%2B%20%E5%9B%A0%E5%AD%90%E4%B8%AD%E6%80%A7%20%2B%20%E6%8D%A2%E6%89%8B%22%5D%0A%20%20Opt%20--%3E%20Exe%5B%22%E6%89%A7%E8%A1%8C%3A%20%E5%85%88%E7%A1%AE%E8%AE%A4%E5%8F%AF%E5%80%9F%E5%86%8D%E5%8D%96%E7%A9%BA%22%5D%0A%20%20Exe%20--%3E%20Hedge%5B%22%E6%AE%8B%E5%B7%AE%E5%AF%B9%E5%86%B2%3A%20%E6%9C%9F%E8%B4%A7%20%E2%86%92%20%E5%8D%95%E6%8A%A5%E5%9F%BA%E5%B7%AE%22%5D%0A%20%20Hedge%20--%3E%20Cap%5B%22%E5%AE%B9%E9%87%8F%E7%9B%91%E6%8E%A7%3A%20%E7%9F%AD%E8%85%BF%E5%85%88%E6%BB%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"多腿赚因子与特异，空腿赚因子反向并付借券。挤仓时空腿的损失非对称（上涨可无限）。再平衡溢价在多空里变成频繁调两边，费用双份。中性若真做成，主收益应来自截面 alpha 而不是 beta。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：空头年借券费 1% 看似小，但若策略年化毛收益 6%、空腿占一倍本金，仅借券就吃掉约六分之一。难借的名字费率可达 20% 以上甚至无券可借——许多「显著」的空头收益在真实费率表面前直接消失。")],-1)),(E(),s(i,null,{default:t(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LS%5B%22%E5%A4%9A%E7%A9%BA%E5%90%84%E4%B8%80%22%5D%20--%3E%20Net%5B%22%E5%87%80%E6%9A%B4%E9%9C%B2%20%E5%AF%B9%E5%86%B2%E5%B7%A5%E5%85%B7%22%5D%0A%20%20LS%20--%3E%20Gross%5B%22%E6%80%BB%E6%9A%B4%E9%9C%B2%20%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%22%5D%0A%20%20Short%5B%22%E7%A9%BA%E8%85%BF%22%5D%20--%3E%20Loan%5B%22%E5%80%9F%E5%88%B8%20%E5%8F%AC%E5%9B%9E%20%E6%8C%A4%E4%BB%93%22%5D%0A%20%20Gross%20--%3E%20IR%5B%22IR%20%E5%88%86%E6%AF%8D%E8%A6%81%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>危机中相关升、空头召回同时发生，中性失效。做空禁令是制度风险。本课不写如何规避借券定位规则。</p><p><span class="marginnote">初学者容易以为「危机里中性组合没事」。实际危机时相关性升向 1、空头被召回、期货基差跳开，三件事同时发生：对冲失效、空腿被迫回补、对冲工具错价。中性是统计平均意义上的性质，不是压力时刻的保证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实盘多空的约束在空腿：可借、成本、挤仓；学术 HML 不是产品。</li><li>同时管净、总、因子；IR 分母对齐。</li><li>期货对冲留下基差，不是完全中性。</li><li>出处：Jacobs and Levy 对多空实施的讨论；Fama–French 排序为学术对照。</li></ul>',5))])}const _=A(p,[["render",h]]);export{F as __pageData,_ as default};
